export function getNextCapaId(currentCapas: any[]): string {
  if (!Array.isArray(currentCapas)) return 'CAPA-2026-001';
  let maxNum = 0;
  currentCapas.forEach(c => {
    if (!c) return;
    const idStr = c.id || c.CAPAID || '';
    const match = idStr.match(/CAPA-2026-(\d+)/);
    if (match && match[1]) {
      const num = parseInt(match[1], 10);
      if (num > maxNum) {
        maxNum = num;
      }
    }
  });
  const nextNum = maxNum + 1;
  const padded = String(nextNum).padStart(3, '0');
  return `CAPA-2026-${padded}`;
}

export function trackDeletedId(key: string, id: string): void {
  try {
    const deletedKey = `${key}_deleted_ids`;
    const current = localStorage.getItem(deletedKey);
    const list = current ? JSON.parse(current) : [];
    if (!Array.isArray(list)) {
      localStorage.setItem(deletedKey, JSON.stringify([id]));
    } else if (!list.includes(id)) {
      list.push(id);
      localStorage.setItem(deletedKey, JSON.stringify(list));
    }
    // Synchronously mark key as dirty and track in localDirtyKeys so onSnapshot respects the deletion
    localStorage.setItem(`${key}_is_dirty`, 'true');
  } catch (e) {
    console.error("[trackDeletedId Error]:", e);
  }
}

export function deduplicateOqcRecords(records: any[]): any[] {
  if (!Array.isArray(records)) return [];
  const seen = new Map<string, any>();
  records.forEach((rec, index) => {
    if (!rec) return;
    let serial = rec.serialNo || '';
    if (typeof serial !== 'string') {
      serial = String(serial);
    }
    const cleanSerial = serial.trim().toUpperCase();
    if (!cleanSerial) {
      const fallbackId = rec.id || `OQC-EMPTY-${Date.now()}-${index}`;
      seen.set(fallbackId, { ...rec, id: fallbackId });
      return;
    }
    
    // Standardize the ID
    const standardId = `OQC-${cleanSerial.replace(/[\/\s.#$\[\]]/g, '_')}`;
    const standardizedRec = { ...rec, id: standardId };

    const existing = seen.get(cleanSerial);
    if (!existing) {
      seen.set(cleanSerial, standardizedRec);
    } else {
      // Smart conflict resolution: keep the one with richer information (defect details, evaluations, treatment, root cause, etc.)
      const score = (r: any) => {
        let sc = 0;
        if (r.defectDetail && String(r.defectDetail).trim()) sc += 2;
        if (r.evaluation && String(r.evaluation).trim()) sc += 2;
        if (r.treatment && String(r.treatment).trim()) sc += 2;
        if (r.rootCause && String(r.rootCause).trim()) sc += 1;
        if (r.status && String(r.status).trim() && r.status !== 'Đạt') sc += 1;
        if (r.failedCount && Number(r.failedCount) > 0) sc += 1;
        return sc;
      };
      if (score(standardizedRec) > score(existing)) {
        seen.set(cleanSerial, standardizedRec);
      }
    }
  });
  return Array.from(seen.values());
}

function getMonthFromDate(dateStr: string): number | null {
  if (!dateStr) return null;
  const cleaned = dateStr.trim();
  if (cleaned.includes('-')) {
    const parts = cleaned.split('-');
    if (parts.length >= 2) {
      const m = parseInt(parts[1], 10);
      return isNaN(m) ? null : m;
    }
  } else if (cleaned.includes('/')) {
    const parts = cleaned.split('/');
    if (parts.length >= 2) {
      const m = parseInt(parts[1], 10);
      return isNaN(m) ? null : m;
    }
  }
  return null;
}

function sanitizeDefects(rawDefects: any[]): MarketDefect[] {
  if (!Array.isArray(rawDefects)) return [];
  return rawDefects.map(d => ({
    ...d,
    feedbackType: d.feedbackType || 'Lỗi xe từ khách hàng',
    status: d.status || 'Chưa xử lý',
    severity: d.severity || 'C'
  }));
}

function resequencePtspTasks(tasksList: PTSPTask[]): PTSPTask[] {
  if (!Array.isArray(tasksList)) return [];
  
  // 1. Nhóm theo projectId
  const projectIds = Array.from(new Set(tasksList.map(t => t.projectId).filter(Boolean)));
  
  const finalTasks: PTSPTask[] = [];
  
  projectIds.forEach(pId => {
    const projTasks = tasksList.filter(t => t.projectId === pId);
    
    // Xử lý từng giai đoạn từ 1 đến 8
    for (let stg = 1; stg <= 8; stg++) {
      const stageTasks = projTasks.filter(t => Number(t.stage) === stg);
      
      // Sắp xếp các tasks trong giai đoạn này:
      stageTasks.sort((a, b) => {
        // Thứ nhất: So sánh theo mã số phụ cũ (ví dụ 1.1 so với 1.2 thì lấy .1, .2) để giữ nguyên thứ tự dữ liệu mẫu nguyên bản
        const getSubCode = (code: string) => {
          if (!code) return 999;
          const parts = code.split('.');
          if (parts.length >= 2) {
            const sub = parseInt(parts[1], 10);
            return isNaN(sub) ? 999 : sub;
          }
          return 999;
        };
        const aSub = getSubCode(a.itemCode);
        const bSub = getSubCode(b.itemCode);
        
        if (aSub !== bSub && aSub !== 999 && bSub !== 999) {
          return aSub - bSub;
        }
        
        // Thứ hai: So sánh theo ngày bắt đầu (startDate)
        const aStart = a.startDate || '';
        const bStart = b.startDate || '';
        if (aStart !== bStart) {
          return aStart.localeCompare(bStart);
        }
        
        // Thứ ba: So sánh theo ngày kết thúc (endDate)
        const aEnd = a.endDate || '';
        const bEnd = b.endDate || '';
        if (aEnd !== bEnd) {
          return aEnd.localeCompare(bEnd);
        }
        
        // Thứ tư: Tránh xáo trộn bằng cách dùng ID hoặc thời gian tạo
        return (a.id || '').localeCompare(b.id || '');
      });
      
      // Sau khi sắp xếp chuẩn, tiến hành gán lại mã itemCode theo thứ tự liên tục 1, 2, 3...
      const resequenced = stageTasks.map((t, idx) => ({
        ...t,
        stage: Number(t.stage),
        itemCode: `${stg}.${idx + 1}`
      }));
      
      finalTasks.push(...resequenced);
    }
    
    // Nếu có tasks nào có stage không hợp lệ (ngoài 1-8 hoặc NaN) thì giữ nguyên
    const otherTasks = projTasks.filter(t => {
      const s = Number(t.stage);
      return isNaN(s) || s < 1 || s > 8;
    });
    finalTasks.push(...otherTasks);
  });
  
  // Những tasks không có projectId
  const noProjTasks = tasksList.filter(t => !t.projectId);
  finalTasks.push(...noProjTasks.map(t => ({ ...t, stage: Number(t.stage) || 1 })));
  
  return finalTasks;
}

function getSavedState<T>(key: string, baseData: T): T {
  try {
    const saved = localStorage.getItem(key);
    if (saved !== null) {
      const parsed = JSON.parse(saved);
      if (parsed === null || parsed === undefined) {
        return baseData;
      }
      if (Array.isArray(baseData) && !Array.isArray(parsed)) {
        return baseData;
      }
      if (key === 'dk_oqc_records' && Array.isArray(parsed)) {
        return deduplicateOqcRecords(parsed) as any;
      }
      if (key === 'dk_defects' && Array.isArray(parsed)) {
        return sanitizeDefects(parsed) as any;
      }
      return parsed;
    }
  } catch (e) {
    console.error(`Error loading state from localStorage for: ${key}`, e);
  }
  if (key === 'dk_oqc_records' && Array.isArray(baseData)) {
    return deduplicateOqcRecords(baseData) as any;
  }
  if (key === 'dk_defects' && Array.isArray(baseData)) {
    return sanitizeDefects(baseData) as any;
  }
  return baseData;
}

function ensureUniqueIds<T extends { id: string }>(arr: T[], prefix: string = 'ITEM'): T[] {
  if (!Array.isArray(arr)) return [];
  const seenIds = new Set<string>();
  return arr.map((item, index) => {
    if (!item) return item;
    if (!item.id) {
      const generatedId = `${prefix}-${Date.now()}-${index}-${Math.floor(Math.random() * 1000)}`;
      return { ...item, id: generatedId };
    }
    const cleanId = item.id.trim();
    if (seenIds.has(cleanId)) {
      let newId = `${cleanId}_dup_${index}_${Math.floor(Math.random() * 1000)}`;
      while (seenIds.has(newId)) {
        newId = `${cleanId}_dup_${index}_${Math.floor(Math.random() * 10000)}`;
      }
      seenIds.add(newId);
      return { ...item, id: newId };
    }
    seenIds.add(cleanId);
    return { ...item, id: cleanId };
  });
}

export function standardizeDate(dateStr: string): string {
  if (!dateStr) return '';
  const trimmed = dateStr.trim();
  if (!trimmed) return '';

  let day = 1;
  let month = 7;
  let year = 2026;
  const today = new Date();
  const currentYear = today.getFullYear() || 2026;
  const currentMonth = today.getMonth() + 1;

  if (trimmed.includes('-')) {
    const parts = trimmed.split('-');
    if (parts[0].length === 4) {
      // YYYY-MM-DD
      year = Number(parts[0]) || currentYear;
      month = Number(parts[1]) || currentMonth;
      day = Number(parts[2]) || 1;
    } else {
      // DD-MM-YYYY or DD-MM
      day = Number(parts[0]) || 1;
      month = Number(parts[1]) || currentMonth;
      year = parts[2] ? (Number(parts[2]) || currentYear) : currentYear;
    }
  } else if (trimmed.includes('/')) {
    const parts = trimmed.split('/');
    if (parts[0].length === 4) {
      // YYYY/MM/DD
      year = Number(parts[0]) || currentYear;
      month = Number(parts[1]) || currentMonth;
      day = Number(parts[2]) || 1;
    } else {
      // DD/MM/YYYY or DD/MM
      day = Number(parts[0]) || 1;
      month = Number(parts[1]) || currentMonth;
      const yrPart = parts[2] ? parts[2].trim() : '';
      year = yrPart ? (yrPart.length === 2 ? 2000 + Number(yrPart) : Number(yrPart)) : currentYear;
    }
  } else {
    const num = Number(trimmed);
    if (!isNaN(num) && num > 0 && num <= 31) {
      day = num;
      month = currentMonth;
      year = currentYear;
    } else {
      return trimmed;
    }
  }

  const dd = String(day).padStart(2, '0');
  const mm = String(month).padStart(2, '0');
  return `${dd}/${mm}/${year}`;
}

export function getWeekAndMonthFromDate(dateStr: string): { week: string; month: number; year: number } {
  const today = new Date();
  const currentYear = today.getFullYear();
  const currentMonth = today.getMonth() + 1;
  const currentDay = today.getDate();

  const getCalendarWeekForDay = (d: number, m: number, y: number): number => {
    const firstDayOfMonth = new Date(y, m - 1, 1);
    const firstDayOfWeek = firstDayOfMonth.getDay(); // 0 = Sunday, 1 = Monday, ..., 6 = Saturday
    const firstSundayDay = firstDayOfWeek === 0 ? 1 : 8 - firstDayOfWeek;

    if (d < firstSundayDay) {
      return 1;
    } else {
      const diff = d - firstSundayDay;
      return 2 + Math.floor(diff / 7);
    }
  };

  const getDefaultWeek = () => {
    const weekNum = getCalendarWeekForDay(currentDay, currentMonth, currentYear);
    return `T${Math.min(5, weekNum)}`;
  };

  if (!dateStr) return { week: getDefaultWeek(), month: currentMonth, year: currentYear };
  
  let day = 1;
  let month = currentMonth;
  let year = currentYear;
  
  if (dateStr.includes('-')) {
    const parts = dateStr.split('-');
    year = Number(parts[0]) || currentYear;
    month = Number(parts[1]) || currentMonth;
    day = Number(parts[2]) || 1;
  } else if (dateStr.includes('/')) {
    const parts = dateStr.split('/');
    day = Number(parts[0]) || 1;
    month = Number(parts[1]) || currentMonth;
    const yrPart = parts[2] ? parts[2].trim() : '';
    year = yrPart ? (yrPart.length === 2 ? 2000 + Number(yrPart) : Number(yrPart)) : currentYear;
  } else {
    return { week: 'T1', month, year };
  }
  
  const weekNum = getCalendarWeekForDay(day, month, year);
  const weekStr = `T${Math.min(5, weekNum)}`;
  return { week: weekStr, month, year };
}

export function getWeekDatesForMonthYear(year: number, month: number, weekKey: string): string {
  const weekNum = parseInt((weekKey || 'T1').replace(/\D/g, '')) || 1;
  const firstDayOfMonth = new Date(year, month - 1, 1);
  const dow = firstDayOfMonth.getDay(); // 0 = Sun, 1 = Mon, ..., 6 = Sat
  
  let mon1Day: number;
  if (dow === 1) mon1Day = 1;
  else if (dow === 2) mon1Day = 0;
  else if (dow === 3) mon1Day = -1;
  else if (dow === 4) mon1Day = -2;
  else if (dow === 5) mon1Day = 4;
  else if (dow === 6) mon1Day = 3;
  else if (dow === 0) mon1Day = 2;
  else mon1Day = 1;

  const monTarget = new Date(year, month - 1, mon1Day + (weekNum - 1) * 7);
  const sunTarget = new Date(monTarget);
  sunTarget.setDate(monTarget.getDate() + 6);

  const pad = (n: number) => n.toString().padStart(2, '0');
  const startStr = `${pad(monTarget.getDate())}/${pad(monTarget.getMonth() + 1)}`;
  const endStr = `${pad(sunTarget.getDate())}/${pad(sunTarget.getMonth() + 1)}`;

  return `${startStr} - ${endStr}`;
}

export function getLastName(fullName: string): string {
  if (!fullName) return '';
  const separators = /[,;/&\\+\|]|\s+và\s+|\s+and\s+/i;
  const parts = fullName.split(separators);
  if (parts.length > 1) {
    return parts
      .map(p => {
        const trimmed = p.trim();
        if (!trimmed) return '';
        const words = trimmed.split(/\s+/);
        return words[words.length - 1] || '';
      })
      .filter(Boolean)
      .join(', ');
  }
  
  const words = fullName.trim().split(/\s+/);
  const knownShortNames = ['Thao', 'Hùng', 'Tùng', 'Phấn', 'Hải', 'Diệm', 'Lâm', 'Việt', 'Bình', 'Huy', 'Minh', 'Nam', 'Trang', 'Sơn', 'Tuấn', 'Quân', 'Dũng', 'Khánh', 'An', 'Bảo', 'Đạt'];
  
  const matchedShortNames = words.filter(word => knownShortNames.some(kn => kn.toLowerCase() === word.toLowerCase()));
  if (matchedShortNames.length > 1 && matchedShortNames.length === words.length) {
    return matchedShortNames.join(', ');
  }
  
  return words[words.length - 1] || '';
}

export function mapOldCategoryToStandard(cat: string): string {
  if (!cat) return 'IQC';
  const c = cat.trim();
  if (['IQC', 'PQC', 'OQC', 'Phát triển sản phẩm', 'Huấn luyện / Đào tạo', 'Cải tiến hiện trường', 'Khách hàng/Bảo hành'].includes(c)) {
    return c;
  }
  if (c === '5S' || c === '6S' || c === 'Kaizen' || c === 'Cải tiến hiện trường (6S/5S/Kaizen)') return 'Cải tiến hiện trường';
  if (c === 'PTSP' || c === 'Phát triển sản phẩm mới (PTSP/R&D)') return 'Phát triển sản phẩm';
  if (c === 'Bảo hành' || c === 'Khách hàng' || c === 'CS' || c === 'Warranty') return 'Khách hàng/Bảo hành';
  if (c === 'KCS đầu ra') return 'OQC';
  if (c === 'Kiểm tra LK NCC') return 'IQC';
  if (c === 'Kiểm tra dv - dk' || c === 'Kiểm tra dv - lr') return 'PQC';
  if (c === 'QA' || c === 'Tang ca' || c === 'Cong viec phat sinh') return 'PQC';
  return 'IQC';
}

export function sanitizeDailyLogs(raw: any[]): DailyLogRecord[] {
  if (!Array.isArray(raw)) return [];
  
  // Filter out auto-generated Market Defect records from Market Defects module per user directive
  const cleanRaw = raw.filter((log) => {
    if (!log) return false;
    const content = String(log.content || '').toLowerCase();
    const note = String(log.note || '').toLowerCase();

    if (
      content.includes('[khai báo lỗi thị trường]') ||
      content.includes('[ghi nhận đề xuất cải tiến thị trường]') ||
      content.includes('[nhập hàng loạt - đề xuất cải tiến]') ||
      content.includes('[nhập hàng loạt - phản ánh kh]') ||
      note.includes('tự động tạo lịch sử phản ánh') ||
      note.includes('tự động tạo từ phản ánh thị trường') ||
      note.includes('tự động tạo từ phân hệ phản ánh')
    ) {
      return false; // Exclude auto-generated market defects from Daily Logs
    }
    return true;
  });

  // Step 1: Filter out duplicate logs with identical key fields
  const seenSignatures = new Map<string, any>();
  cleanRaw.forEach((log) => {
    if (!log) return;

    const content = String(log.content || '').trim().replace(/\s+/g, ' ');
    const date = standardizeDate(String(log.date || '').trim());
    const category = mapOldCategoryToStandard(log.category || 'IQC');
    const assignee = String(log.assignee || '').trim();
    const target = String(log.target || '').trim().replace(/\s+/g, ' ');
    const unit = String(log.unit || '').trim().replace(/\s+/g, ' ');
    const result = String(log.result || '').trim().replace(/\s+/g, ' ');
    const statusPercent = String(log.statusPercent || '0%').trim();
    const note = String(log.note || '').trim().replace(/\s+/g, ' ');
    const year = String(log.year || 2026);
    
    // Modern unique IDs (LOG-<timestamp>-<random>) are guaranteed unique and must bypass deduplication completely
    const idVal = String(log.id || '');
    const isModern = idVal.startsWith('LOG-') && idVal.split('-').length >= 3;
    
    // Create a highly precise signature key to avoid merging different, legitimate logs
    const sigKey = isModern 
      ? `MODERN-${idVal}` 
      : `${date}|${category}|${assignee.toLowerCase()}|${content.toLowerCase()}|${target.toLowerCase()}|${unit.toLowerCase()}|${result.toLowerCase()}|${statusPercent.toLowerCase()}|${note.toLowerCase()}|${year}`;
    
    const existing = seenSignatures.get(sigKey);
    if (!existing) {
      seenSignatures.set(sigKey, log);
    } else {
      // Keep the one with higher completion percentage or non-empty result/notes
      const getScore = (item: any) => {
        let sc = 0;
        const pct = parseInt(String(item.statusPercent || '0')) || 0;
        sc += pct;
        if (item.result && String(item.result).trim()) sc += 10;
        if (item.note && String(item.note).trim()) sc += 5;
        return sc;
      };
      if (getScore(log) > getScore(existing)) {
        seenSignatures.set(sigKey, log);
      }
    }
  });

  const uniqueRawLogs = Array.from(seenSignatures.values());

  let maxStt = 0;
  // Step 2: Initialize list of items, ensure each has a valid index and fields
  const withInitialStt = uniqueRawLogs.map((log, idx) => {
    let stt = log && typeof log.stt === 'number' ? log.stt : parseInt(String(log && log.stt)) || 0;
    if (stt <= 0) {
      stt = idx + 1;
    }
    if (stt > maxStt) {
      maxStt = stt;
    }
    
    const category = mapOldCategoryToStandard((log && log.category) || 'IQC');
    
    let timeWork = log && log.timeWork;
    if (!Array.isArray(timeWork)) {
      timeWork = Array(8).fill('');
    }
    if (timeWork.length < 8) {
      const cloned = [...timeWork];
      while (cloned.length < 8) {
        cloned.push('');
      }
      timeWork = cloned;
    }
    
    const rawDate = (log && log.date) || '';
    const standardizedDateStr = standardizeDate(rawDate);
    const deadlineStr = (log && log.deadline) ? standardizeDate(log.deadline) : standardizedDateStr;

    const id = (log && log.id) || (stt > 0 ? `LOG-${stt}` : `LOG-${Date.now()}-${Math.random().toString(36).substr(2, 5).toUpperCase()}`);

    return {
      id,
      stt,
      date: standardizedDateStr,
      week: (log && log.week) || 'T1',
      category,
      content: (log && log.content) || '',
      target: (log && log.target) || '',
      unit: (log && log.unit) || '',
      assignee: (log && log.assignee) || '',
      timeWork,
      result: (log && log.result) || '',
      deadline: deadlineStr,
      statusPercent: (log && log.statusPercent) || '0%',
      note: (log && log.note) || '',
      year: (log && log.year) || 2026
    };
  });

  // Step 3: Resolve key duplicates
  const seenStts = new Set<number>();
  return withInitialStt.map((log) => {
    let stt = log.stt;
    if (seenStts.has(stt) || stt <= 0) {
      maxStt += 1;
      stt = maxStt;
    }
    seenStts.add(stt);
    return { ...log, stt };
  });
}

export function isLogBeforeTargetWeek(logDate: string, logWeek: string, logYearVal: number | undefined, targetW: string, targetM: number, targetY: number): boolean {
  if (!logDate) return false;
  const info = getWeekAndMonthFromDate(logDate);
  const m = info.month;
  const y = logYearVal || info.year || 2026;
  
  const wNum = parseInt(String(logWeek || '').replace('T', ''), 10) || 1;
  const targetWNum = parseInt(String(targetW || '').replace('T', ''), 10) || 1;
  
  if (y < targetY) return true;
  if (y > targetY) return false;
  
  if (m < targetM) return true;
  if (m > targetM) return false;
  
  return wNum < targetWNum;
}

export function isLogBeforeTargetMonth(logDate: string, logYearVal: number | undefined, targetM: number, targetY: number): boolean {
  if (!logDate) return false;
  const info = getWeekAndMonthFromDate(logDate);
  const m = info.month;
  const y = logYearVal || info.year || 2026;
  
  if (y < targetY) return true;
  if (y > targetY) return false;
  
  return m < targetM;
}

