  const getPtspTaskDuration = (start: string | undefined, end: string | undefined): number => {
    if (!start || !end) return 0;
    const sParts = start.split('-');
    const eParts = end.split('-');
    if (sParts.length !== 3 || eParts.length !== 3) return 0;
    
    const sYear = parseInt(sParts[0], 10);
    const sMonth = parseInt(sParts[1], 10) - 1;
    const sDay = parseInt(sParts[2], 10);
    
    const eYear = parseInt(eParts[0], 10);
    const eMonth = parseInt(eParts[1], 10) - 1;
    const eDay = parseInt(eParts[2], 10);
    
    const sDate = Date.UTC(sYear, sMonth, sDay);
    const eDate = Date.UTC(eYear, eMonth, eDay);
    
    const diffTime = eDate - sDate;
    const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays : 0;
  };

