  const newWeekTaskMonthDates = useMemo(() => {
    const daysInMonth: { [key: number]: number } = {
      1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30, 7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31
    };
    const count = daysInMonth[newWeekTaskMonth] || 31;
    const dates: string[] = [];
    const formattedM = newWeekTaskMonth < 10 ? `0${newWeekTaskMonth}` : `${newWeekTaskMonth}`;
    for (let d = 1; d <= count; d++) {
      const formattedD = d < 10 ? `0${d}` : `${d}`;
      dates.push(`${formattedD}/${formattedM}/2026`);
    }
    return dates;
  }, [newWeekTaskMonth]);

