  const parseCsvOrTsvLine = (line: string): string[] => {
    if (line.includes('\t')) {
      return line.split('\t').map(s => s.trim().replace(/^"|"$/g, ''));
    }
    const result: string[] = [];
    let current = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') {
        inQuotes = !inQuotes;
      } else if (char === ',' && !inQuotes) {
        result.push(current.trim().replace(/^"|"$/g, ''));
        current = '';
      } else {
        current += char;
      }
    }
    result.push(current.trim().replace(/^"|"$/g, ''));
    return result;
  };

  const parseBulkCustomerFeedbackText = (text: string): Partial<MarketDefect>[] => {
    if (!text || !text.trim()) return [];
    const rawLines = text.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);
    if (rawLines.length === 0) return [];

    const parsedRecords: Partial<MarketDefect>[] = [];
    let headerIndices: { [key: string]: number } = {};
    let startRowIndex = 0;

    for (let i = 0; i < Math.min(rawLines.length, 5); i++) {
      const cols = parseCsvOrTsvLine(rawLines[i]);
      const lineJoined = cols.join(' ').toLowerCase();

      if (lineJoined.includes('tổng hợp phản ánh') || cols.every(c => !c)) {
        continue;
      }

      const isHeader = cols.some(c => {
        const low = c.toLowerCase();
        return low.includes('mã phản ánh') || low.includes('ngày nguồn') || low.includes('tên khách hàng') || low.includes('model') || low.includes('chi tiết phản ánh') || low.includes('loại phản ánh');
      });

      if (isHeader) {
        startRowIndex = i + 1;
        cols.forEach((colName, idx) => {
          const low = colName.toLowerCase();
          // Exclude: Mã phản ánh, Nhân viên, Khu vực, Tỉnh/Thành phố, Hình thức tiếp nhận
          if (low.includes('mã phản ánh') || low.includes('nhân viên') || low.includes('khu vực') || low.includes('tỉnh/thành phố') || low.includes('tỉnh') || low.includes('thành phố') || low.includes('hình thức tiếp nhận')) {
            return;
          }

          if (low.includes('ngày nguồn')) headerIndices['sourceDate'] = idx;
          else if (low.includes('tên khách hàng') || low.includes('khách hàng')) headerIndices['customerName'] = idx;
          else if (low.includes('ngày tiếp nhận') || low.includes('ngày phản ánh')) headerIndices['defectDate'] = idx;
          else if (low.includes('model')) headerIndices['model'] = idx;
          else if (low.includes('loại phản ánh gốc') || low.includes('loại phản ánh')) headerIndices['originalCategory'] = idx;
          else if (low.includes('nhóm lỗi') || low.includes('loại lỗi')) headerIndices['type'] = idx;
          else if (low.includes('chi tiết') || low.includes('mô tả')) headerIndices['description'] = idx;
          else if (low.includes('nguyên nhân')) headerIndices['rootCause'] = idx;
          else if (low.includes('phương án') || low.includes('biện pháp') || low.includes('giải quyết')) headerIndices['correction'] = idx;
          else if (low.includes('người thực hiện') || low.includes('người xử lý')) headerIndices['assignee'] = idx;
          else if (low.includes('ngày giải quyết') || low.includes('ngày xong')) headerIndices['targetDate'] = idx;
          else if (low.includes('tình trạng') || low.includes('trạng thái')) headerIndices['status'] = idx;
          else if (low.includes('đánh giá kh') || low.includes('đánh giá')) headerIndices['customerRating'] = idx;
          else if (low.includes('mức độ') || low.includes('cấp độ')) headerIndices['severity'] = idx;
          else if (low.includes('cơ sở') || low.includes('lý do phân loại')) headerIndices['severityRationale'] = idx;
          else if (low.includes('ghi chú')) headerIndices['dataNotes'] = idx;
        });
        break;
      }
    }

    const hasDynamicHeader = Object.keys(headerIndices).length > 0;

    for (let i = startRowIndex; i < rawLines.length; i++) {
      const line = rawLines[i];
      if (!line || line.startsWith('TỔNG HỢP') || line.replace(/,/g, '').trim() === '') continue;

      const cols = parseCsvOrTsvLine(line);
      if (cols.length < 3 || cols.every(c => !c)) continue;

      let sourceDate = '';
      let customerName = '';
      let defectDate = '';
      let model = '';
      let originalCategory = '';
      let type = '';
      let description = '';
      let rootCause = '';
      let correction = '';
      let assignee = '';
      let targetDate = '';
      let status = '';
      let customerRating = '';
      let severity = '';
      let severityRationale = '';
      let dataNotes = '';
      let rawPaCode = '';

      if (hasDynamicHeader) {
        if (headerIndices['sourceDate'] !== undefined) sourceDate = cols[headerIndices['sourceDate']] || '';
        if (headerIndices['customerName'] !== undefined) customerName = cols[headerIndices['customerName']] || '';
        if (headerIndices['defectDate'] !== undefined) defectDate = cols[headerIndices['defectDate']] || '';
        if (headerIndices['model'] !== undefined) model = cols[headerIndices['model']] || '';
        if (headerIndices['originalCategory'] !== undefined) originalCategory = cols[headerIndices['originalCategory']] || '';
        if (headerIndices['type'] !== undefined) type = cols[headerIndices['type']] || '';
        if (headerIndices['description'] !== undefined) description = cols[headerIndices['description']] || '';
        if (headerIndices['rootCause'] !== undefined) rootCause = cols[headerIndices['rootCause']] || '';
        if (headerIndices['correction'] !== undefined) correction = cols[headerIndices['correction']] || '';
        if (headerIndices['assignee'] !== undefined) assignee = cols[headerIndices['assignee']] || '';
        if (headerIndices['targetDate'] !== undefined) targetDate = cols[headerIndices['targetDate']] || '';
        if (headerIndices['status'] !== undefined) status = cols[headerIndices['status']] || '';
        if (headerIndices['customerRating'] !== undefined) customerRating = cols[headerIndices['customerRating']] || '';
        if (headerIndices['severity'] !== undefined) severity = cols[headerIndices['severity']] || '';
        if (headerIndices['severityRationale'] !== undefined) severityRationale = cols[headerIndices['severityRationale']] || '';
        if (headerIndices['dataNotes'] !== undefined) dataNotes = cols[headerIndices['dataNotes']] || '';
      } else {
        // Positional fallback for 21-column sheet
        rawPaCode = cols[0] || '';
        sourceDate = cols[1] || '';
        // Col 2: Nhân viên (EXCLUDED)
        // Col 3: Khu vực (EXCLUDED)
        // Col 4: Tỉnh/Thành phố (EXCLUDED)
        customerName = cols[5] || '';
        defectDate = cols[6] || '';
        // Col 7: Hình thức tiếp nhận (EXCLUDED)
        model = cols[8] || '';
        originalCategory = cols[9] || '';
        type = cols[10] || '';
        description = cols[11] || '';
        rootCause = cols[12] || '';
        correction = cols[13] || '';
        assignee = cols[14] || '';
        targetDate = cols[15] || '';
        status = cols[16] || '';
        customerRating = cols[17] || '';
        severity = cols[18] || '';
        severityRationale = cols[19] || '';
        dataNotes = cols[20] || '';
      }

      if (!description && !model && !type && !customerName) continue;

      const formattedStatus = status.includes('Đã') ? 'Đã xử lý' : status.includes('Đề xuất') ? 'Đề xuất cải tiến' : status.includes('Chưa') ? 'Chưa xử lý' : 'Đang xử lý';

      const item: Partial<MarketDefect> = {
        feedbackType: originalCategory.includes('cải tiến') || type.includes('cải tiến') ? 'Đề xuất cải tiến' : 'Lỗi xe từ khách hàng',
        model: model || 'DK Roma SX',
        dealer: customerName || 'Khách hàng / Đại lý',
        customerName: customerName,
        defectDate: defectDate || new Date().toLocaleDateString('vi-VN'),
        sourceDate: sourceDate,
        originalCategory: originalCategory,
        type: type || 'Khác',
        description: description || 'Nội dung phản ánh từ khách hàng',
        rootCause: rootCause,
        correction: correction,
        assignee: assignee || 'Trưởng nhóm QA/QC',
        targetDate: targetDate,
        status: formattedStatus as any,
        customerRating: customerRating,
        severity: severity || 'Cao',
        severityRationale: severityRationale,
        dataNotes: dataNotes ? (rawPaCode ? `[Mã gốc: ${rawPaCode}] ${dataNotes}` : dataNotes) : (rawPaCode ? `[Mã gốc: ${rawPaCode}]` : ''),
        chassisNo: '',
        engineNo: '',
        saleDate: sourceDate || defectDate
      };

      parsedRecords.push(item);
    }

    return parsedRecords;
  };

  const handleConfirmBulkDefectsImport = () => {
    if (bulkImportParsedPreview.length === 0) return;

    guardAction(() => {
      let currentIdNum = parseInt(nextDefectId.replace(/DEF-/i, ''), 10) || 4010;
      const newItems: MarketDefect[] = [];

      bulkImportParsedPreview.forEach((item, idx) => {
        const generatedId = `DEF-${currentIdNum + idx}`;
        const fType = item.feedbackType || 'Lỗi xe từ khách hàng';
        
        const newDefect: MarketDefect = {
          id: generatedId,
          feedbackType: fType,
          model: item.model || 'DK Roma SX',
          chassisNo: item.chassisNo || '',
          engineNo: item.engineNo || '',
          saleDate: item.saleDate || item.defectDate || new Date().toLocaleDateString('vi-VN'),
          dealer: item.dealer || item.customerName || 'Đại lý',
          customerName: item.customerName || '',
          defectDate: item.defectDate || new Date().toLocaleDateString('vi-VN'),
          sourceDate: item.sourceDate || '',
          originalCategory: item.originalCategory || '',
          type: item.type || 'Sự cố điện',
          description: item.description || '',
          severity: item.severity || 'Cao',
          severityRationale: item.severityRationale || '',
          rootCause: item.rootCause || '',
          correction: item.correction || '',
          assignee: item.assignee || 'Trưởng nhóm QA/QC',
          targetDate: item.targetDate || '',
          status: item.status || 'Chưa xử lý',
          customerRating: item.customerRating || '',
          dataNotes: item.dataNotes || '',
          images: []
        };

        newItems.push(newDefect);
      });

      const updatedDefects = [...newItems, ...defects];
      setDefects(updatedDefects);
      syncToServer('dk_defects', updatedDefects);

      setShowBulkImportDefectsModal(false);
      setBulkImportRawText('');
      setBulkImportParsedPreview([]);

      alert(`Kính gửi anh Thao!\n\nHệ thống đã nhập thành công ${newItems.length} phản ánh khách hàng vào phân hệ Phản ánh Thị trường & đồng bộ lên QMS Firestore!`);
    });
  };

  // Auto-generate project code for PTSP
  const generateNextPtspProjectId = () => {
    let maxNum = 0;
    const arrayToScan = Array.isArray(projects) ? projects : [];
    arrayToScan.forEach((p) => {
      if (p.id) {
        const match = p.id.match(/(?:PROJ|PRJ)-(\d+)/i);
        if (match) {
          const num = parseInt(match[1], 10);
          if (num > maxNum) maxNum = num;
        }
      }
    });
    const nextNum = maxNum > 0 ? maxNum + 1 : 1;
    return `PROJ-${String(nextNum).padStart(3, '0')}`;
  };

  // Auto-generate ECO Code
  const generateNextEcoCode = () => {
    let maxNum = 0;
    const arrayToScan = Array.isArray(ecos) ? ecos : [];
    arrayToScan.forEach((e) => {
      if (e.id) {
        const match = e.id.match(/ECO-(\d+)/i);
        if (match) {
          const num = parseInt(match[1], 10);
          if (num > maxNum) maxNum = num;
        }
      }
    });
    const nextNum = maxNum >= 2601 ? maxNum + 1 : (maxNum > 0 ? maxNum + 1 : 2601);
    return `ECO-${nextNum}`;
  };

  // Auto-generate ECR Code
  const generateNextEcrId = () => {
    let maxNum = 0;
    const arrayToScan = Array.isArray(ecos) ? ecos : [];
    arrayToScan.forEach((e) => {
      if (e.ecrId) {
        const match = e.ecrId.match(/ECR-(\d+)/i);
        if (match) {
          const num = parseInt(match[1], 10);
          if (num > maxNum) maxNum = num;
        }
      }
    });
    const nextNum = maxNum >= 443 ? maxNum + 1 : (maxNum > 0 ? maxNum + 1 : 443);
    return `ECR-${nextNum}`;
  };

  // React states for PTSP project initialization form
  const [addPtspId, setAddPtspId] = useState('');
  const [addPtspName, setAddPtspName] = useState('');
  const [addPtspSelectedMaster, setAddPtspSelectedMaster] = useState('');

  // React states for ECO proposal form
  const [addEcoId, setAddEcoId] = useState('');
  const [addEcoEcrId, setAddEcoEcrId] = useState('');
  const [addEcoModelName, setAddEcoModelName] = useState('');
  const [addEcoSelectedMaster, setAddEcoSelectedMaster] = useState('');

  // Core Audit / Evaluation States
  const [showAuditSupplierModal, setShowAuditSupplierModal] = useState<Supplier | null>(null);
  const [supplierAuditScore, setSupplierAuditScore] = useState({ qms: 80, process: 85, equipment: 75, material: 90 });
  const [supplierAuditNotes, setSupplierAuditNotes] = useState('');

  const [showAuditPtspModal, setShowAuditPtspModal] = useState<PTSPProject | null>(null);
  const [ptspAuditChecklist, setPtspAuditChecklist] = useState({ designFreeze: true, sampleTest: true, pilotAssembly: false, certification: false });
  const [ptspAuditNotes, setPtspAuditNotes] = useState('');

  const [showAuditEcoModal, setShowAuditEcoModal] = useState<ECOChange | null>(null);
  const [ecoAuditChecklist, setEcoAuditChecklist] = useState({ riskAssessed: true, toolingDone: false, sopCreated: false, iqcTestDone: true });
  const [ecoAuditNotes, setEcoAuditNotes] = useState('');

  // Handlers for adding data
  const handleAddSupplierSubmit = (data: Partial<Supplier>) => {
    guardAction(() => {
      // Pre-calculate sequential master ID
      const nextIdNum = suppliers.length > 0 ? Math.max(...suppliers.map(s => {
        const cleaned = (s.id || s.SupplierID || '').replace('NCC', '') || '0';
        return parseInt(cleaned) || 0;
      })) + 1 : 1;
      const formattedSeqId = `NCC${nextIdNum.toString().padStart(5, '0')}`;
      const finalId = data.id || data.SupplierID || formattedSeqId;

      const totalParts = Number(data.totalParts) || 0;
      const faultyParts = Number(data.faultyParts) || 0;
      const calculatedPpm = totalParts > 0 ? Math.round((faultyParts / totalParts) * 1000000) : 0;
      const calculatedDefectRate = totalParts > 0 ? (faultyParts / totalParts * 100).toFixed(2) : 0;

      // Unify quality rating grade based on PPM: A < 500, B < 2000, C < 5000, D >= 5000
      let autogradedRating: 'A' | 'B' | 'C' | 'D' = 'A';
      if (calculatedPpm >= 5000) autogradedRating = 'D';
      else if (calculatedPpm >= 2000) autogradedRating = 'C';
      else if (calculatedPpm >= 500) autogradedRating = 'B';

      const finalRating = data.QualityRating || autogradedRating;

      const newSup: Supplier = {
        id: finalId,
        SupplierID: finalId,
        name: data.name || data.SupplierName || '',
        SupplierName: data.name || data.SupplierName || '',
        ComponentType: data.ComponentType || 'Chưa định nghĩa',
        suppliedComponentCount: Number(data.suppliedComponentCount) || 1,
        totalParts: totalParts,
        faultyParts: faultyParts,
        defectRate: calculatedDefectRate,
        PPM: calculatedPpm,
        trends: [0, 0, calculatedPpm],
        defectTypes: data.defectTypes || [],
        QualityRating: finalRating,
        LastAuditDate: data.LastAuditDate || new Date().toLocaleDateString('vi-VN'),
        Status: 'Active',
        address: data.address,
        phone: data.phone
      };
      setSuppliers([newSup, ...suppliers]);
      alert(`Đã hoàn tất ký kết & đăng ký Nhà Cung Cấp: ${newSup.SupplierName} (Mã số: ${finalId})`);
    });
  };

  const handleAutoFixMismatchedSuppliers = () => {
    guardAction(() => {
      let fixCount = 0;
      const updatedSuppliers = suppliers.map((sup) => {
        const comp = (sup.ComponentType || '').trim();
        const lowerComp = comp.toLowerCase();
        const addressKeywords = [
          'đường', 'phố', 'quận', 'huyện', 'tỉnh', 'tp', 'thành phố', 'hà nội', 'hải phòng', 
          'khu công nghiệp', 'kcn', 'phòng', 'lô', 'cụm', 'số', 'ấp', 'xã', 'thị', 'đà nẵng',
          'bắc ninh', 'bắc giang', 'hà nam', 'hưng yên', 'hải dương', 'vĩnh phúc', 'thái nguyên', 
          'nam định', 'ninh bình', 'thái bình', 'quảng ninh', 'thanh hóa', 'nghệ an', 'hà tĩnh', 
          'bình dương', 'đồng nai', 'long an', 'vĩnh long', 'cần thơ', 'khánh hòa', 'lâm đồng', 
          'bà rịa', 'vũng tàu', 'hồ chí minh', 'sài gòn'
        ];
        
        const hasAddressKeyword = addressKeywords.some(kw => lowerComp.includes(kw));
        
        if (hasAddressKeyword) {
          fixCount++;
          return {
            ...sup,
            ComponentType: sup.address || 'Không xác định',
            address: sup.ComponentType
          };
        }
        return sup;
      });

      if (fixCount > 0) {
        setSuppliers(updatedSuppliers);
        alert(`🎉 Hệ thống đã quét và sửa đổi/hoán vị thành công ${fixCount} Nhà Cung Cấp bị nhầm lẫn thông tin Linh kiện & Địa chỉ cho anh Thao!`);
      } else {
        alert("🔍 Không phát hiện thấy Nhà cung cấp nào bị nhầm lẫn thông tin (trường Linh kiện chứa địa chỉ)!");
      }
    });
  };

  const handleBulkAddSuppliers = (e: FormEvent) => {
    e.preventDefault();
    if (!bulkSupplierInput.trim()) {
      alert("Vui lòng nhập danh sách nhà cung cấp!");
      return;
    }
    
    guardAction(() => {
      const lines = bulkSupplierInput.split('\n');
      const addedSuppliers: Supplier[] = [];
      let nextIdNum = suppliers.length > 0 ? Math.max(...suppliers.map(s => {
        const cleaned = (s.id || s.SupplierID || '').replace('NCC', '') || '0';
        return parseInt(cleaned) || 0;
      })) + 1 : 1;

      lines.forEach(line => {
        const cleanLine = line.trim();
        if (!cleanLine) return;

        let parts = cleanLine.split('|');
        if (parts.length < 2) {
          parts = cleanLine.split('\t');
        }
        if (parts.length < 2) {
          parts = cleanLine.split(',');
        }

        const name = parts[0]?.trim();
        if (!name) return;

        let address = '';
        let phone = '';
        let componentType = 'Tổng hợp';
        let qualityRating: 'A' | 'B' | 'C' | 'D' = 'B';

        const isPhoneNumber = (str: string) => /^[0-9+\s\-().]{7,25}$/.test(str.trim());
        const containsAddressKeyword = (str: string) => {
          const lower = str.toLowerCase();
          const addressKeywords = [
            'đường', 'phố', 'quận', 'huyện', 'tỉnh', 'tp', 'thành phố', 'hà nội', 'hải phòng', 
            'khu công nghiệp', 'kcn', 'phòng', 'lô', 'cụm', 'số', 'ấp', 'xã', 'thị', 'đà nẵng',
            'bắc ninh', 'bắc giang', 'hà nam', 'hưng yên', 'hải dương', 'vĩnh phúc', 'thái nguyên', 
            'nam định', 'ninh bình', 'thái bình', 'quảng ninh', 'thanh hóa', 'nghệ an', 'hà tĩnh', 
            'bình dương', 'đồng nai', 'long an', 'vĩnh long', 'cần thơ', 'khánh hòa', 'lâm đồng', 
            'bà rịa', 'vũng tàu', 'hồ chí minh', 'sài gòn'
          ];
          return addressKeywords.some(kw => lower.includes(kw));
        };

        const isComponentType = (str: string) => {
          const lower = str.toLowerCase();
          const componentKeywords = [
            'sườn', 'khung', 'yên', 'lốp', 'ắc quy', 'pin', 'sạc', 'ic', 'điều tốc', 'động cơ', 
            'nhựa', 'má phanh', 'phanh', 'gương', 'đèn', 'vành', 'nan hoa', 'xích', 'líp', 'đĩa', 
            'cáp', 'dây', 'ghi đông', 'pô tang', 'giảm xóc', 'phuộc', 'phụ tùng', 'linh kiện', 
            'vỏ', 'ruột', 'motor', 'charger', 'battery', 'tyre', 'wheel'
          ];
          return componentKeywords.some(kw => lower.includes(kw));
        };

        if (parts.length >= 3) {
          const part2 = parts[1].trim();
          const part3 = parts[2].trim();
          
          if (isPhoneNumber(part3) || containsAddressKeyword(part2) || !isComponentType(part2) || part3.length > 8) {
            // New format: Tên NCC | Địa chỉ NCC | SĐT
            address = part2;
            phone = part3;
          } else {
            // Old format: Tên NCC | Linh kiện | Hạng
            componentType = part2;
            let ratingRaw = part3.toUpperCase();
            if (['A', 'B', 'C', 'D'].includes(ratingRaw)) {
              qualityRating = ratingRaw as 'A' | 'B' | 'C' | 'D';
            }
          }
        } else if (parts.length === 2) {
          const part2 = parts[1].trim();
          if (isPhoneNumber(part2)) {
            phone = part2;
          } else if (containsAddressKeyword(part2) || !isComponentType(part2)) {
            address = part2;
          } else {
            componentType = part2;
          }
        }

        const finalId = `NCC${nextIdNum.toString().padStart(5, '0')}`;
        nextIdNum++;

        addedSuppliers.push({
          id: finalId,
          SupplierID: finalId,
          name: name,
          SupplierName: name,
          ComponentType: componentType,
          suppliedComponentCount: 1,
          totalParts: 0,
          faultyParts: 0,
          defectRate: 0,
          PPM: 0,
          trends: [0, 0, 0],
          defectTypes: [],
          QualityRating: qualityRating,
          LastAuditDate: new Date().toLocaleDateString('vi-VN'),
          Status: 'Active',
          address: address || undefined,
          phone: phone || undefined
        });
      });

      if (addedSuppliers.length === 0) {
        alert("⚠️ Không phát hiện dữ liệu nhà cung cấp nào hợp lệ. Định dạng mẫu: Tên Nhà Cung Cấp | Địa chỉ | SĐT");
        return;
      }

      setSuppliers(prev => [...addedSuppliers, ...prev]);
      setBulkSupplierInput('');
      setIsBulkSupplierMode(false);
      alert(`🎉 Đã thêm thành công hàng loạt ${addedSuppliers.length} Nhà Cung Cấp mới vào hệ thống!`);
    });
  };

  const handleBulkAddDealers = (e: FormEvent) => {
    e.preventDefault();
    if (!bulkDealerInput.trim()) {
      alert("Vui lòng nhập danh sách đại lý / khách hàng!");
      return;
    }

    guardAction(() => {
      const lines = bulkDealerInput.split('\n');
      const addedDealers: Dealer[] = [];
      let nextIdNum = dealers.length > 0 ? Math.max(...dealers.map(d => {
        const cleaned = d.id?.replace('DLR-', '') || '0';
        return parseInt(cleaned) || 0;
      })) + 1 : 1;

      lines.forEach(line => {
        const cleanLine = line.trim();
        if (!cleanLine) return;

        let parts = cleanLine.split('|');
        if (parts.length < 2) {
          parts = cleanLine.split('\t');
        }
        if (parts.length < 2) {
          parts = cleanLine.split(',');
        }

        const name = parts[0]?.trim();
        if (!name) return;

        let phone = '';
        let address = '';

        if (parts.length >= 3) {
          const part2 = parts[1].trim();
          const part3 = parts[2].trim();

          const isPhoneNumber = (str: string) => /^[0-9+\s\-().]{7,25}$/.test(str.trim());
          
          if (isPhoneNumber(part3)) {
            // New format: Tên Khách hàng | Địa chỉ Khách hàng | SĐT
            address = part2;
            phone = part3;
          } else if (isPhoneNumber(part2)) {
            // Old format: Tên đại lý | SĐT | Địa chỉ
            phone = part2;
            address = part3;
          } else {
            // Fallback
            address = part2;
            phone = part3;
          }
        } else if (parts.length === 2) {
          const part2 = parts[1].trim();
          const isPhoneNumber = (str: string) => /^[0-9+\s\-().]{7,25}$/.test(str.trim());
          if (isPhoneNumber(part2)) {
            phone = part2;
          } else {
            address = part2;
          }
        }

        const finalId = `DLR-${nextIdNum.toString().padStart(2, '0')}`;
        nextIdNum++;

        addedDealers.push({
          id: finalId,
          name: name,
          phone: phone || undefined,
          address: address || undefined
        });
      });

      if (addedDealers.length === 0) {
        alert("⚠️ Không phát hiện dữ liệu khách hàng / đại lý nào hợp lệ. Định dạng mẫu: Tên Khách hàng | Địa chỉ | SĐT");
        return;
      }

      setDealers(prev => [...addedDealers, ...prev]);
      setBulkDealerInput('');
      setIsBulkDealerMode(false);
      alert(`🎉 Đã thêm thành công hàng loạt ${addedDealers.length} Đại lý / Khách hàng mới vào danh bạ!`);
    });
  };

  const handleUnifiedBulkImportSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!bulkImportText.trim()) {
      alert("Vui lòng nhập dữ liệu để thực hiện nhập hàng loạt!");
      return;
    }

    const lines = bulkImportText.split('\n');
    
    if (bulkImportType === 'supplier') {
      const addedSuppliers: Supplier[] = [];
      let nextIdNum = suppliers.length > 0 ? Math.max(...suppliers.map(s => {
        const cleaned = (s.id || s.SupplierID || '').replace('NCC', '') || '0';
        return parseInt(cleaned) || 0;
      })) + 1 : 1;

      lines.forEach(line => {
        const cleanLine = line.trim();
        if (!cleanLine) return;

        let parts = cleanLine.split('|');
        if (parts.length < 2) parts = cleanLine.split('\t');
        if (parts.length < 2) parts = cleanLine.split(',');

        const name = parts[0]?.trim();
        if (!name) return;

        let address = '';
        let phone = '';
        let componentType = 'Tổng hợp';
        let qualityRating: 'A' | 'B' | 'C' | 'D' = 'B';

        const isPhoneNumber = (str: string) => /^[0-9+\s\-().]{7,25}$/.test(str.trim());
        const containsAddressKeyword = (str: string) => {
          const lower = str.toLowerCase();
          const addressKeywords = [
            'đường', 'phố', 'quận', 'huyện', 'tỉnh', 'tp', 'thành phố', 'hà nội', 'hải phòng', 
            'khu công nghiệp', 'kcn', 'phòng', 'lô', 'cụm', 'số', 'ấp', 'xã', 'thị', 'đà nẵng',
            'bắc ninh', 'bắc giang', 'hà nam', 'hưng yên', 'hải dương', 'vĩnh phúc', 'thái nguyên', 
            'nam định', 'ninh bình', 'thái bình', 'quảng ninh', 'thanh hóa', 'nghệ an', 'hà tĩnh', 
            'bình dương', 'đồng nai', 'long an', 'vĩnh long', 'cần thơ', 'khánh hòa', 'lâm đồng', 
            'bà rịa', 'vũng tàu', 'hồ chí minh', 'sài gòn'
          ];
          return addressKeywords.some(kw => lower.includes(kw));
        };

        const isComponentType = (str: string) => {
          const lower = str.toLowerCase();
          const componentKeywords = [
            'sườn', 'khung', 'yên', 'lốp', 'ắc quy', 'pin', 'sạc', 'ic', 'điều tốc', 'động cơ', 
            'nhựa', 'má phanh', 'phanh', 'gương', 'đèn', 'vành', 'nan hoa', 'xích', 'líp', 'đĩa', 
            'cáp', 'dây', 'ghi đông', 'pô tang', 'giảm xóc', 'phuộc', 'phụ tùng', 'linh kiện', 
            'vỏ', 'ruột', 'motor', 'charger', 'battery', 'tyre', 'wheel'
          ];
          return componentKeywords.some(kw => lower.includes(kw));
        };

        if (parts.length >= 3) {
          const part2 = parts[1].trim();
          const part3 = parts[2].trim();
          
          if (isPhoneNumber(part3) || containsAddressKeyword(part2) || !isComponentType(part2) || part3.length > 8) {
            address = part2;
            phone = part3;
          } else {
            componentType = part2;
            let ratingRaw = part3.toUpperCase();
            if (['A', 'B', 'C', 'D'].includes(ratingRaw)) {
              qualityRating = ratingRaw as 'A' | 'B' | 'C' | 'D';
            }
          }
        } else if (parts.length === 2) {
          const part2 = parts[1].trim();
          if (isPhoneNumber(part2)) {
            phone = part2;
          } else if (containsAddressKeyword(part2) || !isComponentType(part2)) {
            address = part2;
          } else {
            componentType = part2;
          }
        }

        const finalId = `NCC${nextIdNum.toString().padStart(5, '0')}`;
        nextIdNum++;

        addedSuppliers.push({
          id: finalId,
          SupplierID: finalId,
          name: name,
          SupplierName: name,
          ComponentType: componentType,
          suppliedComponentCount: 1,
          totalParts: 0,
          faultyParts: 0,
          defectRate: 0,
          PPM: 0,
          trends: [0, 0, 0],
          defectTypes: [],
          QualityRating: qualityRating,
          LastAuditDate: new Date().toLocaleDateString('vi-VN'),
          Status: 'Active',
          address: address || undefined,
          phone: phone || undefined
        });
      });

      if (addedSuppliers.length === 0) {
        alert("⚠️ Không phát hiện dòng dữ liệu nào hợp lệ. Định dạng mẫu: Tên Nhà Cung Cấp | Địa chỉ | SĐT");
        return;
      }

      setSuppliers(prev => [...addedSuppliers, ...prev]);
      setBulkImportText('');
      setShowBulkImportModal(false);
      alert(`🎉 Đã thêm thành công hàng loạt ${addedSuppliers.length} Nhà Cung Cấp mới vào hệ thống, anh Thao nhé!`);
    } else {
      const addedDealers: Dealer[] = [];
      let nextIdNum = dealers.length > 0 ? Math.max(...dealers.map(d => {
        const cleaned = d.id?.replace('DLR-', '') || '0';
        return parseInt(cleaned) || 0;
      })) + 1 : 1;

      lines.forEach(line => {
        const cleanLine = line.trim();
        if (!cleanLine) return;

        let parts = cleanLine.split('|');
        if (parts.length < 2) parts = cleanLine.split('\t');
        if (parts.length < 2) parts = cleanLine.split(',');

        const name = parts[0]?.trim();
        if (!name) return;

        let phone = '';
        let address = '';

        if (parts.length >= 3) {
          const part2 = parts[1].trim();
          const part3 = parts[2].trim();

          const isPhoneNumber = (str: string) => /^[0-9+\s\-().]{7,25}$/.test(str.trim());
          
          if (isPhoneNumber(part3)) {
            address = part2;
            phone = part3;
          } else if (isPhoneNumber(part2)) {
            phone = part2;
            address = part3;
          } else {
            address = part2;
            phone = part3;
          }
        } else if (parts.length === 2) {
          const part2 = parts[1].trim();
          const isPhoneNumber = (str: string) => /^[0-9+\s\-().]{7,25}$/.test(str.trim());
          if (isPhoneNumber(part2)) {
            phone = part2;
          } else {
            address = part2;
          }
        }

        const finalId = `DLR-${nextIdNum.toString().padStart(2, '0')}`;
        nextIdNum++;

        addedDealers.push({
          id: finalId,
          name: name,
          phone: phone || undefined,
          address: address || undefined
        });
      });

      if (addedDealers.length === 0) {
        alert("⚠️ Không phát hiện dòng dữ liệu nào hợp lệ. Định dạng mẫu: Tên Khách hàng | Địa chỉ | SĐT");
        return;
      }

      setDealers(prev => [...addedDealers, ...prev]);
      setBulkImportText('');
      setShowBulkImportModal(false);
      alert(`🎉 Đã thêm thành công hàng loạt ${addedDealers.length} Khách hàng mới vào hệ thống, anh Thao nhé!`);
    }
  };

