  const handleOpenEditModal = (type: 'task' | 'supplier' | 'capa' | 'ptsp' | 'defect' | 'eco' | 'copq' | 'form' | 'staff' | 'model' | 'daily_log' | 'fmea' | 'dealer' | 'improvement_action', item: any) => {
    if (type === 'staff' && !isStaffAdmin()) {
      alert("⚠️ BẢO MẬT: Chỉ anh Thao mới có quyền Thêm/Xóa/Quản lý danh sách nhân sự của phòng!");
      return;
    }
    if (type === 'defect') {
      const currentDealer = item.dealer || item.Dealer || '';
      setEditDefectDealerSearch(currentDealer);
      const currentModel = item.model || item.VehicleModel || '';
      setEditDefectModelSearch(currentModel);
    }
    setGlobalEditModal({
      type,
      data: JSON.parse(JSON.stringify(item))
    });
  };

  const handleDeleteItem = (type: 'task' | 'supplier' | 'capa' | 'ptsp' | 'defect' | 'eco' | 'copq' | 'form' | 'staff' | 'model' | 'fmea' | 'dealer' | 'improvement_action', id: string) => {
    guardAction(() => {
      if (window.confirm(`⚠️ BẠN CÓ CHẮC CHẮN MUỐN XÓA BẢN GHI NÀY CỦA PHÂN HỆ [${type.toUpperCase()}] KHÔNG?\nHành động xóa không thể khôi phục tự động.`)) {
        const keyMap: Record<string, string> = {
          task: 'dk_tasks',
          capa: 'dk_capas',
          eco: 'dk_ecos',
          copq: 'dk_copqs',
          ptsp: 'dk_projects',
          defect: 'dk_defects',
          fmea: 'dk_fmea',
          form: 'dk_custom_forms',
          staff: 'dk_staff',
          model: 'dk_models',
          dealer: 'dk_dealers',
          improvement_action: 'dk_improvement_actions'
        };
        const mappedKey = keyMap[type];
        if (mappedKey) {
          trackDeletedId(mappedKey, id);
        }
        if (type === 'ptsp') {
          trackDeletedId('dk_ptsp_tasks', id);
        }
        switch (type) {
          case 'task': {
            const updated = tasks.filter(t => t.id !== id);
            setTasks(updated);
            syncToServer('dk_tasks', updated);
            break;
          }
          case 'supplier': {
            const updated = suppliers.filter(s => s.id !== id);
            setSuppliers(updated);
            syncToServer('dk_suppliers', updated);
            break;
          }
          case 'capa': {
            const updatedCapas = capas.filter(c => c.id !== id);
            setCapas(updatedCapas);
            syncToServer('dk_capas', updatedCapas);

            const updatedDefects = defects.map(d => {
              if (d.capaId === id) {
                return { ...d, capaId: '', status: 'Chưa xử lý' };
              }
              return d;
            });
            setDefects(updatedDefects);
            syncToServer('dk_defects', updatedDefects);
            break;
          }
          case 'ptsp': {
            const remains = projects.filter(p => p.id !== id);
            setProjects(remains);
            syncToServer('dk_projects', remains);
            if (selectedPtspProject === id) {
              if (remains.length > 0) {
                setSelectedPtspProject(remains[0].id);
              } else {
                setSelectedPtspProject('');
              }
            }
            const updatedPtspTasks = ptspTasks.filter(t => t.projectId !== id);
            setPtspTasks(updatedPtspTasks);
            syncToServer('dk_ptsp_tasks', updatedPtspTasks);
            break;
          }
          case 'defect': {
            const updated = defects.filter(d => d.id !== id);
            setDefects(updated);
            syncToServer('dk_defects', updated);
            break;
          }
          case 'improvement_action': {
            const actionToDelete = improvementActions.find(act => act.id === id);
            const targetDefectId = actionToDelete?.defectId;
            
            const updatedDefects = defects.map(d => {
              if ((targetDefectId && d.id === targetDefectId) || (d.capaId && (d.capaId === id || d.capaId === actionToDelete?.id))) {
                return { ...d, capaId: '', status: 'Chưa xử lý' };
              }
              return d;
            });
            setDefects(updatedDefects);
            localStorage.setItem('dk_defects', JSON.stringify(updatedDefects));
            localStorage.setItem('dk_defects_is_dirty', 'true');
            syncToServer('dk_defects', updatedDefects);

            const updatedActions = improvementActions.filter(act => act.id !== id);
            setImprovementActions(updatedActions);
            localStorage.setItem('dk_improvement_actions', JSON.stringify(updatedActions));
            localStorage.setItem('dk_improvement_actions_is_dirty', 'true');
            syncToServer('dk_improvement_actions', updatedActions);
            break;
          }
          case 'fmea': {
            const updated = fmea.filter(f => f.id !== id);
            setFmea(updated);
            syncToServer('dk_fmea', updated);
            break;
          }
          case 'eco': {
            const updated = ecos.filter(ec => ec.id !== id);
            setEcos(updated);
            syncToServer('dk_ecos', updated);
            break;
          }
          case 'copq': {
            const updated = copqs.filter(co => co.id !== id);
            setCopqs(updated);
            syncToServer('dk_copqs', updated);
            break;
          }
          case 'form': {
            const updated = customForms.filter(cf => cf.id !== id);
            setCustomForms(updated);
            syncToServer('dk_custom_forms', updated);
            break;
          }
          case 'staff': {
            if (!isStaffAdmin()) {
              alert("⚠️ BẢO MẬT: Chỉ anh Thao mới có quyền Thêm/Xóa/Quản lý danh sách nhân sự của phòng!");
              return;
            }
            const updated = staff.filter(s => s.id !== id);
            setStaff(updated);
            syncToServer('dk_staff', updated);
            break;
          }
          case 'model': {
            const updated = models.filter(m => m.id !== id);
            setModels(updated);
            syncToServer('dk_models', updated);
            break;
          }
          case 'dealer': {
            const updated = dealers.filter(d => d.id !== id);
            setDealers(updated);
            syncToServer('dk_dealers', updated);
            break;
          }
        }
        alert("Đã xóa bản ghi thành công!");
      }
    });
  };

  // States for Daily QA/QC Logs (Báo cáo ngày)
  const [logSearch, setLogSearch] = useState('');
