  // Dynamic linkage of Supplier PPM evaluations and statistics based on live IQC records
  const computedSuppliers = useMemo(() => {
    return suppliers.map(s => {
      const relatedIqc = iqcRecords.filter(r => r.supplierId === s.id || r.supplierName === s.name);
      
      if (relatedIqc.length > 0) {
        const totalParts = relatedIqc.reduce((acc, r) => acc + (r.totalQty || 0), 0);
        const faultyParts = relatedIqc.reduce((acc, r) => acc + (r.failedQty || 0), 0);
        const PPM = totalParts > 0 ? Math.round((faultyParts / totalParts) * 1000000) : 0;
        
        const customDefectTypes = relatedIqc
          .filter(r => r.result === 'Lỗi' && r.defectDetail)
          .map(r => r.defectDetail || '');
        const uniqDefectTypes = Array.from(new Set(customDefectTypes));
        const defectTypes = uniqDefectTypes.length > 0 ? uniqDefectTypes : s.defectTypes || ['Kiểm thử đạt tiêu chuẩn vạch dòng'];

        let QualityRating: 'A' | 'B' | 'C' | 'D' = 'A';
        if (PPM >= 5000) QualityRating = 'D';
        else if (PPM >= 2000) QualityRating = 'C';
        else if (PPM >= 500) QualityRating = 'B';
        
        return {
          ...s,
          totalParts,
          faultyParts,
          defectRate: PPM,
          PPM,
          defectTypes,
          status: QualityRating,
          QualityRating,
          suppliedComponentCount: relatedIqc.length
        };
      } else {
        const totalParts = s.totalParts || 0;
        const faultyParts = s.faultyParts || 0;
        const PPM = totalParts > 0 ? Math.round((faultyParts / totalParts) * 1000000) : 0;
        let QualityRating: 'A' | 'B' | 'C' | 'D' = 'A';
        if (PPM >= 5000) QualityRating = 'D';
        else if (PPM >= 2000) QualityRating = 'C';
        else if (PPM >= 500) QualityRating = 'B';

        return {
          ...s,
          totalParts,
          faultyParts,
          defectRate: PPM,
          PPM,
          status: QualityRating,
          QualityRating,
          defectTypes: s.defectTypes && s.defectTypes.length > 0 ? s.defectTypes : ['Chưa có đợt nhập kiểm trong kỳ']
        };
      }
    });
  }, [suppliers, iqcRecords]);

