  const getDocumentDateParts = (applyDateStr?: string) => {
    const now = new Date();
    let day = now.getDate() < 10 ? '0' + now.getDate() : String(now.getDate());
    let month = (now.getMonth() + 1) < 10 ? '0' + (now.getMonth() + 1) : String(now.getMonth() + 1);
    let year = '2026';

    if (applyDateStr) {
      if (applyDateStr.includes('/')) {
        const parts = applyDateStr.split('/');
        if (parts.length >= 3) {
          day = parts[0].padStart(2, '0');
          month = parts[1].padStart(2, '0');
          year = parts[2];
        }
      } else if (applyDateStr.includes('-')) {
        const parts = applyDateStr.split('-');
        if (parts.length >= 3) {
          if (parts[0].length === 4) {
            year = parts[0];
            month = parts[1].padStart(2, '0');
            day = parts[2].padStart(2, '0');
          } else {
            day = parts[0].padStart(2, '0');
            month = parts[1].padStart(2, '0');
            year = parts[2];
          }
        }
      }
    }
    return { day, month, year };
  };

