  // Computed metrics
  const activeTasksForMetrics = tasks && tasks.length > 0 ? tasks : INITIAL_TASKS;
  const totalTasks = activeTasksForMetrics.length;
  // Rule check helper: Result >= Target => Completed
  const completedTasks = activeTasksForMetrics.filter(t => t.result >= t.target).length;
  const taskCompletionRate = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;
  
  // Rule check helper: Count tasks with >= 2 weeks unresolved
  const unresolvedTasksCount = activeTasksForMetrics.filter(t => t.weeksUnresolved && t.weeksUnresolved >= 2).length;
  // Overdue count
  const overdueTasksCount = activeTasksForMetrics.filter(t => t.status === 'Overdue').length;

  // Average Supplier PPM
  const avgPPM = Math.round(
    computedSuppliers.reduce((acc, s) => acc + s.defectRate, 0) / (computedSuppliers.length || 1)
  );

  // Overall COPQ budget
  const totalCOPQ = copqs.reduce((acc, c) => acc + c.amount, 0);

  // Rank D Suppliers & Rising PPM warning check (continuous monthly increase)
  const highRiskSuppliers = useMemo(() => {
    return computedSuppliers.filter(s => {
      const isRankD = s.status === 'D' || s.defectRate >= 5000;
      // PPM increasing for 3 consecutive steps?
      const isRisingTrend = s.trends.length >= 3 && s.trends[2] > s.trends[1] && s.trends[1] > s.trends[0];
      return isRankD || isRisingTrend;
    });
  }, [computedSuppliers]);

  // Red Warning Market Defects (cháy, chập điện, mất phanh, gãy khung, mất điều khiển)
  const redAlertDefects = useMemo(() => {
    return defects.filter(d => {
      const descLower = d.description.toLowerCase();
      const typeLower = d.type.toLowerCase();
      return (
        descLower.includes('cháy') || typeLower.includes('cháy') ||
        descLower.includes('chập điện') || typeLower.includes('chập điện') ||
        descLower.includes('mất phanh') || typeLower.includes('mất phanh') ||
        descLower.includes('gãy khung') || typeLower.includes('gãy') ||
        descLower.includes('mất điều khiển') || typeLower.includes('điều khiển')
      );
    });
  }, [defects]);

  // Repeated defects alert (same error description/symptom appearing >= 3 times)
  const repeatedDefects = useMemo(() => {
    const counts: Record<string, number> = {};
    const repeatedDescs: string[] = [];
    defects.forEach(d => {
      const descKey = (d.description || '').trim().toLowerCase();
      if (descKey) {
        counts[descKey] = (counts[descKey] || 0) + 1;
      }
    });
    Object.keys(counts).forEach(descKey => {
      if (counts[descKey] >= 3) {
        repeatedDescs.push(descKey);
      }
    });
    return defects.filter(d => {
      const descKey = (d.description || '').trim().toLowerCase();
      return descKey ? repeatedDescs.includes(descKey) : false;
    });
  }, [defects]);

  // Báo cáo ngày (Daily QA/QC logs) computed metrics and filters
  const filteredDailyLogs = useMemo(() => {
    return dailyLogs.filter(log => {
      if (!log) return false;
      
      // Search
      const logContent = log.content || '';
      const logNote = log.note || '';
      const logCategoryStr = log.category || '';
      const logAssigneeStr = log.assignee || '';
      
      const matchSearch = logSearch === '' || 
        logContent.toLowerCase().includes(logSearch.toLowerCase()) || 
        logNote.toLowerCase().includes(logSearch.toLowerCase()) || 
        logCategoryStr.toLowerCase().includes(logSearch.toLowerCase()) || 
        logAssigneeStr.toLowerCase().includes(logSearch.toLowerCase());
      
      // Week
      const matchWeek = logWeek === 'All' || log.week === logWeek;
      
      // Category
      const matchCategory = logCategory === 'All' || log.category === logCategory;
      
      // Assignee
      const matchAssignee = logAssignee === 'All' || logAssigneeStr.toLowerCase().includes(logAssignee.toLowerCase());
      
      // Exact Date Filter
      const matchDate = logDateFilter === 'All' || log.date === logDateFilter;

      // Month Filter
      const logMonth = log.date ? (parseInt(log.date.split('/')[1]) || 5) : 5;
      const matchMonth = logMonthFilter === 'All' || logMonth === logMonthFilter;

      // Year Filter
      const logYear = log.year || 2026;
      const matchYear = logYearFilter === 'All' || logYear === logYearFilter;

      // Status
      let matchStatus = true;
      if (logStatus !== 'All') {
        const percent = log.statusPercent ? (parseInt(typeof log.statusPercent === 'string' ? log.statusPercent.replace('%', '') : String(log.statusPercent)) || 0) : 0;
        if (logStatus === 'Completed') {
          matchStatus = percent >= 100;
        } else if (logStatus === 'In Progress') {
          matchStatus = percent > 0 && percent < 100;
        } else if (logStatus === 'Not Started') {
          matchStatus = percent === 0;
        }
      }
      
      return matchSearch && matchWeek && matchCategory && matchAssignee && matchStatus && matchDate && matchMonth && matchYear;
    });
  }, [dailyLogs, logSearch, logWeek, logCategory, logAssignee, logStatus, logDateFilter, logMonthFilter, logYearFilter]);

  const paginatedDailyLogs = useMemo(() => {
    const startIndex = (logPage - 1) * logLimit;
    return filteredDailyLogs.slice(startIndex, startIndex + logLimit);
  }, [filteredDailyLogs, logPage, logLimit]);

  const logStats = useMemo(() => {
    let completed = 0;
    let inProgress = 0;
    let notStarted = 0;
    let sumPercent = 0;
    
    filteredDailyLogs.forEach(log => {
      if (!log) return;
      const percent = log.statusPercent ? (parseInt(typeof log.statusPercent === 'string' ? log.statusPercent.replace('%', '') : String(log.statusPercent)) || 0) : 0;
      sumPercent += percent;
      
      if (percent >= 100) {
        completed++;
      } else if (percent > 0) {
        inProgress++;
      } else {
        notStarted++;
      }
    });
    
    const avgCompletion = filteredDailyLogs.length > 0 
      ? Math.round(sumPercent / filteredDailyLogs.length) 
      : 0;
      
    return {
      total: filteredDailyLogs.length,
      completed,
      inProgress,
      notStarted,
      avgCompletion
    };
  }, [filteredDailyLogs]);

