                      let initialDateStr = `${y}-${m}-${d}`;
                      if (logDateFilter && logDateFilter !== 'All') {
                        const parts = logDateFilter.split('/');
                        if (parts.length === 3) {
                          initialDateStr = `${parts[2]}-${parts[1].padStart(2, '0')}-${parts[0].padStart(2, '0')}`;
                        } else if (parts.length === 2) {
                          initialDateStr = `2026-${parts[1].padStart(2, '0')}-${parts[0].padStart(2, '0')}`;
                        }
                      }
                      setSelectedExportDateStr(initialDateStr);
                      setShowExportDateModal(true);
