                const applyDate = fd.get('applyDate') as string;

                const updated = improvementActions.map(act => {
                  if (act.id === selectedActionForEcoUpdate.id) {
                    return {
                      ...act,
                      status,
                      ecoResult,
                      applyDate: applyDate ? applyDate.split('-').reverse().join('/') : ''
                    };
                  }
                  return act;
                });

                setImprovementActions(updated);
                localStorage.setItem('dk_improvement_actions', JSON.stringify(updated));
                
                setShowUpdateEcoModal(false);
                setSelectedActionForEcoUpdate(null);
                alert(`Đã cập nhật thành công kết quả ECO cho hành động ${selectedActionForEcoUpdate.id}!`);
